// 许可内层之外的HMCB摘要必须绑定完整世界字节，不能交换同tick分支或接受尾随数据。
#include "resident/kernel/continuation_binding.hpp"
#include <iostream>
using namespace hanmo::resident;
namespace {
int checks=0;
// 每条断言检查真实bind/unbind输出，不用同名成功桩。
void check(bool ok,const char* label){++checks;if(!ok)throw std::runtime_error(label);}
ContinuationSnapshot sample(){ContinuationSnapshot value;value.source_identity.world_id[0]=7;value.source_identity.execution_epoch=3;value.source_identity.revision=5;value.source_identity.tick=4;value.actor_id="actor.player";value.action_id="action:1";value.action_kind="travel";value.wallet_id="private";value.action_start_tick=1;value.started_tick=2;value.max_half_days=4;value.max_gross_outflow=100;value.committed_half_days=1;value.gross_outflow=7;value.stop=RunStop::cancelled;return value;}
}
// 固定短世界字节足以验证摘要边界，世界语义继续由native候选恢复核验。
int main(){try{const Bytes checkpoint{1,2,3},other{1,2,4};auto bound=bind_continuation_checkpoint(sample(),checkpoint);check(bound.ok&&bound.value.size()<=continuation_snapshot_byte_limit,"valid snapshot binds to checkpoint");auto decoded=unbind_continuation_checkpoint(bound.value,checkpoint);check(decoded.ok&&decoded.value.actor_id=="actor.player"&&decoded.value.committed_half_days==1&&decoded.value.gross_outflow==7,"matching full world digest restores typed context");auto swapped=unbind_continuation_checkpoint(bound.value,other);check(!swapped.ok&&swapped.error.original.code=="ContinuationCheckpointMismatch","swapped world bytes cannot reuse context");auto corrupted=bound.value;corrupted[5]=corrupted[5]=='0'?'1':'0';auto digest=unbind_continuation_checkpoint(corrupted,checkpoint);check(!digest.ok&&digest.error.original.code=="ContinuationCheckpointMismatch","altered digest refused");corrupted=bound.value;corrupted.push_back(0);check(!unbind_continuation_checkpoint(corrupted,checkpoint).ok,"trailing bytes refused by strict inner codec");corrupted=bound.value;corrupted.resize(continuation_snapshot_byte_limit+1);check(!unbind_continuation_checkpoint(corrupted,checkpoint).ok,"oversized bound context refused");corrupted=bound.value;corrupted[4]=2;check(!unbind_continuation_checkpoint(corrupted,checkpoint).ok,"unknown wrapper version refused");corrupted=bound.value;corrupted[69]='X';check(!unbind_continuation_checkpoint(corrupted,checkpoint).ok,"invalid inner signature refused");bool all_short=true;for(std::size_t n=0;n<bound.value.size();++n)if(unbind_continuation_checkpoint(Bytes(bound.value.begin(),bound.value.begin()+n),checkpoint).ok)all_short=false;check(all_short,"all truncated prefixes refused");auto invalid=sample();invalid.gross_outflow=101;check(!bind_continuation_checkpoint(invalid,checkpoint).ok,"binding cannot sanitize invalid inner budget");std::cout<<"CONTINUATION_BINDING "<<checks<<" checks 0 failures\n";return 0;}catch(const std::exception& error){std::cerr<<"CONTINUATION_BINDING_FAILURE "<<error.what()<<" after "<<checks<<" checks\n";return 1;}}
